import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"构建 CMS 组件 - October CMS - 3.x","titleTemplate":false,"description":"使用自定义组件扩展 CMS。","frontmatter":{"subtitle":"使用自定义组件扩展 CMS。"},"headers":[{"level":2,"title":"组件类定义","slug":"组件类定义","link":"#组件类定义","children":[{"level":3,"title":"组件注册","slug":"组件注册","link":"#组件注册","children":[]}]},{"level":2,"title":"组件属性","slug":"组件属性","link":"#组件属性","children":[]},{"level":2,"title":"路由参数","slug":"路由参数","link":"#路由参数","children":[]},{"level":2,"title":"处理页面执行周期","slug":"处理页面执行周期","link":"#处理页面执行周期","children":[{"level":3,"title":"页面执行生命周期处理程序","slug":"页面执行生命周期处理程序","link":"#页面执行生命周期处理程序","children":[]},{"level":3,"title":"组件初始化","slug":"组件初始化","link":"#组件初始化","children":[]},{"level":3,"title":"通过响应停止","slug":"通过响应停止","link":"#通过响应停止","children":[]}]},{"level":2,"title":"AJAX 处理程序","slug":"ajax-处理程序","link":"#ajax-处理程序","children":[]},{"level":2,"title":"默认标记","slug":"默认标记","link":"#默认标记","children":[]},{"level":2,"title":"组件片段","slug":"组件片段","link":"#组件片段","children":[{"level":3,"title":"引用\\"自身\\"","slug":"引用-自身","link":"#引用-自身","children":[]},{"level":3,"title":"唯一标识符","slug":"唯一标识符","link":"#唯一标识符","children":[]}]},{"level":2,"title":"从代码渲染片段","slug":"从代码渲染片段","link":"#从代码渲染片段","children":[]},{"level":2,"title":"通过组件注入页面资源","slug":"通过组件注入页面资源","link":"#通过组件注入页面资源","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/cms-components.md","filePath":"3.x/zh-cn/extend/cms-components.md"}'),u={name:"3.x/zh-cn/extend/cms-components.md"};function r(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"构建 CMS 组件",-1)),a(p),n[1]||(n[1]=i(`<p>组件文件和目录位于插件目录的 <strong>components</strong> 子目录中。每个组件都有一个定义组件类的 PHP 文件和一个可选的组件片段目录。组件片段目录名称与组件类名称的小写形式相匹配。组件目录结构示例如下：</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>components</code>
|           |   ├── blogposts  <em>← Partials Directory</em>
|           |   |   └── default.htm  <em>← Default Markup (Optional)</em>
|           |   └── BlogPosts.php  <em>← Component Class</em>
|           └── Plugin.php</p>
</code></pre><p>组件必须在<a href="./../extend/extending.html">插件注册文件</a>中使用 <code>registerComponents</code> 方法进行<a href="./../extend/extending.html">注册</a>。组件可以使用属性及其 <a href="./../element/inspector-types.html">inspector 类型定义</a>进行配置。</p><h2 id="组件类定义"><a href="#组件类定义" class="header-anchor">#</a> 组件类定义</h2><p><code>create:component</code> 命令用于创建新的组件类和默认组件视图。第一个参数指定作者和插件名称。第二个参数指定组件类名称。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:component Acme.Blog BlogPosts
</code></pre></div><p>组件类文件定义了组件的功能和组件属性。组件类文件名应与组件类名匹配。组件类应继承 <code>Cms\\Classes\\ComponentBase</code> 类。下一个示例中的组件应定义在 <strong>plugins/acme/blog/components/BlogPosts.php</strong> 文件中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">BlogPosts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">componentDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Displays a collection of blog posts.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-puzzle-piece&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * posts becomes available on the page as {{ component.posts }}
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;First Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Second Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Third Post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>componentDetails</code> 方法是必需的。该方法应返回一个包含两个键的数组：<code>name</code> 和 <code>description</code>。名称和描述将显示在 CMS 后端用户界面中。</p><p>当此<a href="./../cms/themes/components.html">组件附加到页面或布局</a>时，类的属性和方法将通过组件变量在页面上可用，变量名与组件短名称或别名匹配。例如，如果上一个示例中的 BlogPost 组件使用其短名称定义在页面上：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPosts</span><span class="token punctuation">]</span></span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
</code></pre></div><p>您可以通过 <code>blogPosts</code> 变量访问其 <code>posts</code> 方法。请注意，Twig 支持方法的属性表示法，因此您不需要使用括号。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> blogPosts<span class="token punctuation">.</span>posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="组件注册"><a href="#组件注册" class="header-anchor">#</a> 组件注册</h3><p>组件必须通过在<a href="./../extend/extending.html">插件注册文件</a>中重写 <code>registerComponents</code> 方法来注册。这会告知 CMS 有关该组件的信息，并提供一个用于使用它的<strong>短名称</strong>。注册组件的示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Todo</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;demoTodo&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这将注册 Todo 组件类，其默认别名为 <strong>demoTodo</strong>。有关使用组件的更多信息，请参阅 <a href="./../cms/themes/components.html">CMS 组件文章</a>。</p><h2 id="组件属性"><a href="#组件属性" class="header-anchor">#</a> 组件属性</h2><p>当您将组件添加到页面或布局时，可以使用属性对其进行配置。属性通过组件类的 <code>defineProperties</code> 方法定义。下一个示例展示了如何使用 <strong>string</strong> inspector 类型定义组件属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Max items&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The most amount of todo items allowed&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;regex&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Max Items property can contain only numeric symbols.&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;pattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[0-9]+$&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>该方法应返回一个以属性键为索引、属性参数为值的数组。属性键用于在组件类内部访问组件属性值。</p><div class="custom-block tip"><p>属性参数和可用类型在 <a href="./../element/inspector-types.html">inspector 类型文章</a>中描述。</p></div><p>在组件内部，您可以使用 <code>property</code> 方法读取属性值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果属性值未定义，您可以将默认值作为 <code>property</code> 方法的第二个参数提供：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以以数组形式加载所有属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$properties</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要从组件的 Twig 片段中访问属性，请使用 <code>__SELF__</code> 变量，它引用组件对象：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>property<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>maxItems<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="路由参数"><a href="#路由参数" class="header-anchor">#</a> 路由参数</h2><p>组件可以直接访问在<a href="./../cms/themes/pages.html">页面 URL</a> 中定义的路由参数值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns the URL segment value, eg: /page/:post_id</span>
<span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在某些情况下，组件属性可以作为硬编码值或引用 URL 中的值。以下硬编码示例展示了使用标识符 <code>2</code> 的博客文章：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/hard-coded-page</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">2</span>&quot;</span>
</code></pre></div><p>或者，可以使用<a href="./../cms/themes/components.html">组件中的外部属性值</a>从页面 URL 动态引用该值。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:my_custom_parameter</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :my_custom_parameter }}</span>&quot;</span>
</code></pre></div><p>在两种情况下，都可以使用 <code>property</code> 方法检索该值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果您需要访问路由参数名称：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns &quot;my_custom_parameter&quot;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">paramName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="处理页面执行周期"><a href="#处理页面执行周期" class="header-anchor">#</a> 处理页面执行周期</h2><p>组件可以通过在组件类中重写 <code>onRun</code> 方法来参与页面执行周期事件。CMS 控制器在每次页面或布局加载时执行此方法。在该方法内部，您可以通过 <code>page</code> 属性向 Twig 环境注入变量：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed when the page or layout is</span>
    <span class="token comment">// loaded and the component is attached to it.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span> <span class="token comment">// Inject some variable to the page</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="页面执行生命周期处理程序"><a href="#页面执行生命周期处理程序" class="header-anchor">#</a> 页面执行生命周期处理程序</h3><p>当页面加载时，October 执行可以在布局和页面 PHP 部分以及组件类中定义的处理函数。处理程序的执行顺序如下。</p><ol><li>布局 <code>onInit()</code> 函数。</li><li>页面 <code>onInit()</code> 函数。</li><li>布局 <code>onStart()</code> 函数。</li><li>布局组件 <code>onRun()</code> 方法。</li><li>布局 <code>onBeforePageStart()</code> 函数。</li><li>页面 <code>onStart()</code> 函数。</li><li>页面组件 <code>onRun()</code> 方法。</li><li>页面 <code>onEnd()</code> 函数。</li><li>布局 <code>onEnd()</code> 函数。</li></ol><h3 id="组件初始化"><a href="#组件初始化" class="header-anchor">#</a> 组件初始化</h3><p>有时您可能希望在组件类首次实例化时执行代码。您可以在组件类中重写 <code>init</code> 方法来处理任何初始化逻辑，这将在 AJAX 处理程序和页面执行生命周期之前执行。例如，此方法可用于动态地将另一个组件附加到页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addComponent</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>BlogPosts</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="通过响应停止"><a href="#通过响应停止" class="header-anchor">#</a> 通过响应停止</h3><p>与<a href="./../cms/themes/layouts.html">布局执行生命周期</a>中的所有方法一样，如果组件中的 <code>onRun</code> 方法返回一个值，这将在此处停止周期并将响应返回给浏览器。以下示例使用 <code>Response</code> facade 返回一条拒绝访问的消息：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Access denied!&#39;</span><span class="token punctuation">,</span> <span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以从 <code>onRun</code> 方法返回 404 响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span><span class="token operator">-&gt;</span><span class="token function">run</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;404&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="ajax-处理程序"><a href="#ajax-处理程序" class="header-anchor">#</a> AJAX 处理程序</h2><p>组件可以托管 AJAX 事件处理程序。它们在组件类中的定义方式与在<a href="./../cms/ajax/handlers.html">页面或布局代码</a>中的定义方式完全相同。以下是在组件类中定义的 AJAX 处理方法示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onAddItem</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$value1</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$value2</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$value1</span> <span class="token operator">+</span> <span class="token variable">$value2</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果此组件的别名为 <em>demoTodo</em>，则可以通过 <code>demoTodo::onAddItem</code> 访问此处理程序。请参阅 <a href="./../cms/ajax/handlers.html">AJAX 处理程序文章</a>了解如何在组件中使用 AJAX。</p><h2 id="默认标记"><a href="#默认标记" class="header-anchor">#</a> 默认标记</h2><p>所有组件都可以带有默认标记，当使用 <code>{% component %}</code> 标签将其包含到页面中时会使用该默认标记，但这是可选的。默认标记保存在<strong>组件片段目录</strong>中，该目录与组件类名称的小写形式同名。</p><p>默认组件标记应放置在名为 <strong>default.htm</strong> 的文件中。例如，Demo ToDo 组件的默认标记定义在文件 <strong>/plugins/october/demo/components/todo/default.htm</strong> 中。然后可以使用 <code>{% component %}</code> 标签将其插入页面的任何位置：</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>默认标记还可以接受在渲染时覆盖组件属性的参数。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>7<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>这些属性在 <code>onRun</code> 方法中不可用，因为它们是在页面周期完成后才确定的。相反，可以通过在组件类中重写 <code>onRender</code> 方法来处理它们。CMS 控制器在渲染默认标记之前执行此方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed before the default component</span>
    <span class="token comment">// markup is rendered on the page or layout.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Maximum items allowed: &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="组件片段"><a href="#组件片段" class="header-anchor">#</a> 组件片段</h2><p>除了默认标记之外，组件还可以提供可在前端或默认标记本身中使用的额外片段。如果 Demo ToDo 组件有一个 <strong>pagination</strong> 片段，它将位于 <strong>/plugins/october/demo/components/todo/pagination.htm</strong>，并使用以下方式在页面上显示：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo::pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>还可以使用一种上下文相关的宽松方法。如果在组件片段内部调用，它将直接引用自身。如果在主题片段内部调用，它将扫描页面/布局上使用的所有组件以查找匹配的片段名称并使用它。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>多个组件可以通过将片段文件放置在名为 <strong>components/partials</strong> 的目录中来共享片段。当找不到常规组件片段时，此目录中的片段将用作后备。例如，位于 <strong>/plugins/acme/blog/components/partials/shared.htm</strong> 的共享片段可以由任何组件使用以下方式在页面上显示：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@shared<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="引用-自身"><a href="#引用-自身" class="header-anchor">#</a> 引用&quot;自身&quot;</h3><p>组件可以在其片段内部使用 <code>__SELF__</code> 变量引用自身。默认情况下，它将返回<a href="./../cms/themes/components.html">组件的短名称或别名</a>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token delimiter punctuation">}}</span></span>::onEventHandler<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    [...]
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>组件也可以引用自身的属性。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> __SELF__<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>如果在组件片段内部需要渲染另一个组件片段，请将 <code>__SELF__</code> 变量与片段名称连接：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> __SELF__<span class="token operator">~</span><span class="token string"><span class="token punctuation">&quot;</span>::screenshot-list<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="唯一标识符"><a href="#唯一标识符" class="header-anchor">#</a> 唯一标识符</h3><p>如果在同一页面上调用了相同的组件两次，可以使用 <code>id</code> 属性来引用每个实例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token punctuation">.</span>id<span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>每次显示组件时，ID 都是唯一的。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- ID: demoTodo527c532e9161b --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- ID: demoTodo527c532ec4c33 --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="从代码渲染片段"><a href="#从代码渲染片段" class="header-anchor">#</a> 从代码渲染片段</h2><p>您可以在 PHP 代码中使用 <code>renderPartial</code> 方法以编程方式渲染组件片段。这将检查组件中名为 <code>component-partial.htm</code> 的片段并以字符串形式返回结果。第二个参数用于传递视图变量。在 PHP 中渲染组件片段时，适用与 Twig 中相同的路径解析逻辑；使用 <code>@</code> 前缀引用组件自身内部的片段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;John Smith&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>例如，将片段作为 <a href="./../cms/ajax/handlers.html">AJAX 处理程序</a>的响应进行渲染：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onGetTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#someDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>另一个示例是通过从 <code>onRun</code> 页面执行周期返回值来覆盖整个页面视图响应。此代码将使用 <code>Response</code> facade 专门返回 XML 响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@default.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="通过组件注入页面资源"><a href="#通过组件注入页面资源" class="header-anchor">#</a> 通过组件注入页面资源</h2><p>组件可以向其附加的页面或布局注入资源（CSS 和 JavaScript 文件）。使用控制器的 <code>addCss</code> 和 <code>addJs</code> 方法向 CMS 控制器添加资源。这可以在组件的 <code>onRun</code> 方法中完成。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果 <code>addCss</code> 和 <code>addJs</code> 方法参数中指定的路径以斜杠（<code>/</code>）开头，则它将相对于网站根目录。如果资源路径不以斜杠开头，则它相对于组件目录。</p><p><code>addCss</code> 和 <code>addJs</code> 方法提供第二个参数，以数组形式定义注入资源的属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../element/inspector-types.html">Inspector 类型</a></li></ul></div>`,101))])}const w=e(u,[["render",r]]);export{f as __pageData,w as default};
